ContactFlow.Content:
{
  "Version": "2019-10-30",
  "StartAction": "start-logging",
  "Metadata": {
    "Annotations": [
      {
        "type": "default",
        "id": "note-redaction",
        "content": "CONSOLE STEP REQUIRED: insert 'Set recording, analytics and processing behavior' here — channel Chat, enable in-flight sensitive-data redaction, select the wisecalls-dev-message-processor Lambda as the custom message processor integration. See docs/04-connect-configuration.md 4.4.",
        "actionId": "start-logging",
        "isFolded": false
      },
      {
        "type": "default",
        "id": "note-ai-agent",
        "content": "OPTIONAL ENHANCEMENT: replace this menu with the Amazon Q in Connect AI Agent block. AI Agent resources already exist and are published: Public Self Service = 44c11800-b308-46c9-b2bf-a4ca6db48891 (before verification), Authenticated Self Service = 03a8ea78-c09b-41ea-b8e2-7e34b2f3d1eb (after verification). Both use assistant 7cfe1848-2fa2-4cf5-9799-40c474ec2a8f and knowledge base 1ee99728-47f1-4b3c-a0d7-0bb3bcf61384. Console step: add the AI Agent block, pick the matching agent ID, and associate the wisecalls-* flow modules as its tools. See docs/04-connect-configuration.md 4.5 and 4.8.",
        "actionId": "main-menu",
        "isFolded": false
      },
      {
        "type": "default",
        "id": "note-verify",
        "content": "Real Lambda-based verification, same mechanism as the voice flow: customer types their registered mobile number (chat has no ANI to match automatically), identify_by_phone looks it up in CoreDataTable, start_otp_verification sends a 6-digit SMS OTP via SNS (90s TTL, enforced server-side), verify_otp checks it and only then sets customerVerified=true. Typing anything that isn't a real phone number (including SKIP) safely falls through to the unverified/public path since the Lambda rejects invalid phone formats. SNS SMS is in sandbox mode — verified destination numbers only until production access is requested.",
        "actionId": "ask-phone",
        "isFolded": false
      }
    ]
  },
  "Actions": [
    {
      "Identifier": "start-logging",
      "Type": "UpdateFlowLoggingBehavior",
      "Parameters": { "FlowLoggingBehavior": "Enabled" },
      "Transitions": { "NextAction": "set-public-state" }
    },
    {
      "Identifier": "set-public-state",
      "Type": "UpdateContactAttributes",
      "Parameters": {
        "Attributes": { "customerVerified": "false", "trustState": "PUBLIC" },
        "TargetContact": "Current"
      },
      "Transitions": {
        "NextAction": "ask-phone",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "ask-phone" } ]
      }
    },
    {
      "Identifier": "ask-phone",
      "Type": "GetParticipantInput",
      "Parameters": {
        "Text": "Welcome to WiseCalls! To verify your identity for account access, reply with your registered mobile number, e.g. +61491570156. Or reply SKIP to continue without verifying.",
        "StoreInput": "True",
        "InputTimeLimitSeconds": "60",
        "InputValidation": {
          "CustomValidation": { "MaximumLength": "20" }
        }
      },
      "Transitions": {
        "NextAction": "save-phone-input",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "greeting-unknown" } ]
      }
    },
    {
      "Identifier": "save-phone-input",
      "Type": "UpdateContactAttributes",
      "Parameters": {
        "Attributes": { "phone": "$.StoredCustomerInput" },
        "TargetContact": "Current"
      },
      "Transitions": {
        "NextAction": "call-identify-module",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "greeting-unknown" } ]
      }
    },
    {
      "Identifier": "call-identify-module",
      "Type": "InvokeFlowModule",
      "Parameters": { "FlowModuleId": "2eb549de-406f-49dd-91cf-fa8219e49cb4" },
      "Transitions": {
        "NextAction": "check-identify-result",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "greeting-unknown" } ]
      }
    },
    {
      "Identifier": "check-identify-result",
      "Type": "Compare",
      "Parameters": { "ComparisonValue": "$.Attributes.identify_found" },
      "Transitions": {
        "NextAction": "greeting-unknown",
        "Conditions": [
          { "NextAction": "greeting-known", "Condition": { "Operator": "Equals", "Operands": ["true"] } }
        ],
        "Errors": [ { "ErrorType": "NoMatchingCondition", "NextAction": "greeting-unknown" } ]
      }
    },
    {
      "Identifier": "greeting-known",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "Thanks, $.Attributes.identify_firstName — we found your account. We'll text a verification code to the mobile number on file." },
      "Transitions": {
        "NextAction": "call-start-otp-module",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "call-start-otp-module",
      "Type": "InvokeFlowModule",
      "Parameters": { "FlowModuleId": "d2b36350-dff2-4f95-a5a2-f10abbafbe90" },
      "Transitions": {
        "NextAction": "ask-otp",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "ask-otp",
      "Type": "GetParticipantInput",
      "Parameters": {
        "Text": "Please reply with the 6 digit code we just texted you. It expires in 90 seconds.",
        "StoreInput": "True",
        "InputTimeLimitSeconds": "90",
        "InputValidation": {
          "CustomValidation": { "MaximumLength": "6" }
        }
      },
      "Transitions": {
        "NextAction": "save-otp-input",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "save-otp-input",
      "Type": "UpdateContactAttributes",
      "Parameters": {
        "Attributes": { "otp_entered": "$.StoredCustomerInput" },
        "TargetContact": "Current"
      },
      "Transitions": {
        "NextAction": "call-verify-otp-module",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "call-verify-otp-module",
      "Type": "InvokeFlowModule",
      "Parameters": { "FlowModuleId": "9f61f43c-3b3c-49c8-b5b4-013064ee700e" },
      "Transitions": {
        "NextAction": "check-verify-result",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "check-verify-result",
      "Type": "Compare",
      "Parameters": { "ComparisonValue": "$.Attributes.otp_verified" },
      "Transitions": {
        "NextAction": "verification-failed-message",
        "Conditions": [
          { "NextAction": "set-verified-true", "Condition": { "Operator": "Equals", "Operands": ["true"] } }
        ],
        "Errors": [ { "ErrorType": "NoMatchingCondition", "NextAction": "verification-failed-message" } ]
      }
    },
    {
      "Identifier": "set-verified-true",
      "Type": "UpdateContactAttributes",
      "Parameters": {
        "Attributes": { "customerVerified": "true", "customerId": "$.Attributes.identify_customerId" },
        "TargetContact": "Current"
      },
      "Transitions": {
        "NextAction": "verified-message",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "verified-message",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "Thanks, $.Attributes.identify_firstName. You're verified." },
      "Transitions": {
        "NextAction": "main-menu",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "verification-failed-message",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "Sorry, that code didn't match or has expired. I'll continue without verifying you for now." },
      "Transitions": {
        "NextAction": "main-menu",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "greeting-unknown",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "No worries — continuing without verification. You can still ask about public rates and ATM/branch locations." },
      "Transitions": {
        "NextAction": "main-menu",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "main-menu" } ]
      }
    },
    {
      "Identifier": "main-menu",
      "Type": "GetParticipantInput",
      "Parameters": {
        "StoreInput": "False",
        "InputTimeLimitSeconds": "60",
        "Text": "Reply 1 for product rates, 2 for the nearest ATM/branch, 4 to share your location securely, or 3 to speak with an agent."
      },
      "Transitions": {
        "NextAction": "invalid-input",
        "Conditions": [
          { "NextAction": "invoke-product-rate", "Condition": { "Operator": "Equals", "Operands": ["1"] } },
          { "NextAction": "invoke-atm-locator", "Condition": { "Operator": "Equals", "Operands": ["2"] } },
          { "NextAction": "set-target-queue", "Condition": { "Operator": "Equals", "Operands": ["3"] } },
          { "NextAction": "call-create-location-module", "Condition": { "Operator": "Equals", "Operands": ["4"] } }
        ],
        "Errors": [
          { "ErrorType": "InputTimeLimitExceeded", "NextAction": "set-target-queue" },
          { "ErrorType": "NoMatchingCondition", "NextAction": "invalid-input" },
          { "ErrorType": "NoMatchingError", "NextAction": "set-target-queue" }
        ]
      }
    },
    {
      "Identifier": "invalid-input",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "Sorry, I did not understand that. Let's try again." },
      "Transitions": {
        "NextAction": "main-menu",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "set-target-queue" } ]
      }
    },
    {
      "Identifier": "invoke-product-rate",
      "Type": "UpdateContactAttributes",
      "Parameters": {
        "Attributes": { "productCode": "CAR_LOAN_STANDARD" },
        "TargetContact": "Current"
      },
      "Transitions": {
        "NextAction": "call-product-rate-module",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "set-target-queue" } ]
      }
    },
    {
      "Identifier": "call-product-rate-module",
      "Type": "InvokeFlowModule",
      "Parameters": { "FlowModuleId": "672c33e4-d41e-4aff-ad52-a9883aff6c6e" },
      "Transitions": {
        "NextAction": "rate-result-message",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "set-target-queue" } ]
      }
    },
    {
      "Identifier": "call-create-location-module",
      "Type": "InvokeFlowModule",
      "Parameters": { "FlowModuleId": "1f300764-1c7f-4f41-9a4c-221f3f49c3c0" },
      "Transitions": {
        "NextAction": "check-location-sms-result",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "set-target-queue" } ]
      }
    },
    {
      "Identifier": "check-location-sms-result",
      "Type": "Compare",
      "Parameters": { "ComparisonValue": "$.Attributes.location_smsSent" },
      "Transitions": {
        "NextAction": "location-no-phone-message",
        "Conditions": [
          { "NextAction": "location-result-message", "Condition": { "Operator": "Equals", "Operands": ["true"] } }
        ],
        "Errors": [ { "ErrorType": "NoMatchingCondition", "NextAction": "location-no-phone-message" } ]
      }
    },
    {
      "Identifier": "location-result-message",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "We've texted you a secure link to the mobile number you provided. Open it, sign in, and grant location permission to share your current position with us." },
      "Transitions": {
        "NextAction": "end-chat",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "end-chat" } ]
      }
    },
    {
      "Identifier": "location-no-phone-message",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "I don't have a valid mobile number for you yet. Please provide your registered mobile number earlier in the chat, then try again." },
      "Transitions": {
        "NextAction": "end-chat",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "end-chat" } ]
      }
    },
    {
      "Identifier": "rate-result-message",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "One moment — I have retrieved the current published rate for our standard car loan product. An agent can read out the exact figures, or this response will be read by the AI agent once configured in the console." },
      "Transitions": {
        "NextAction": "end-chat",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "end-chat" } ]
      }
    },
    {
      "Identifier": "invoke-atm-locator",
      "Type": "MessageParticipant",
      "Parameters": { "Text": "To find the nearest ATM or branch, please share your location, or tell us your suburb." },
      "Transitions": {
        "NextAction": "end-chat",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "end-chat" } ]
      }
    },
    {
      "Identifier": "set-target-queue",
      "Type": "UpdateContactTargetQueue",
      "Parameters": {
        "QueueId": "arn:aws:connect:ap-southeast-2:111122223333:instance/aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee/queue/dcc369d7-d5c2-4ee3-9a52-0d10b0219a60"
      },
      "Transitions": {
        "NextAction": "escalate-to-queue",
        "Errors": [ { "ErrorType": "NoMatchingError", "NextAction": "escalate-to-queue" } ]
      }
    },
    {
      "Identifier": "escalate-to-queue",
      "Type": "TransferContactToQueue",
      "Parameters": {},
      "Transitions": {
        "NextAction": "end-chat",
        "Errors": [
          { "ErrorType": "QueueAtCapacity", "NextAction": "end-chat" },
          { "ErrorType": "NoMatchingError", "NextAction": "end-chat" }
        ]
      }
    },
    {
      "Identifier": "end-chat",
      "Type": "DisconnectParticipant",
      "Parameters": {},
      "Transitions": {}
    }
  ]
}
